import{_ as n,o as e,c as i,a6 as t}from"./chunks/framework.DycQjAfF.js";const m=JSON.parse('{"title":"SOP Penyimpanan Barang","description":"Memindahkan material yang lolos pemeriksaan ke lokasi simpan sesuai klasifikasinya, dengan prinsip FIFO dan FEFO.","frontmatter":{"title":"SOP Penyimpanan Barang","description":"Memindahkan material yang lolos pemeriksaan ke lokasi simpan sesuai klasifikasinya, dengan prinsip FIFO dan FEFO.","status":"ditinjau","dasar":"Instruksi Kerja Penempatan Material/Barang Gudang Teknik dan moto Gudang Teknik","nomor_dokumen":null,"versi":0.3,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-20T00:00:00.000Z","kategori":"SOP","sumber":["ik-gudang-teknik","ppt-gudang-teknik"],"kata_kunci":["SOP","penyimpanan","penempatan","put-away","FIFO","FEFO","rak","bin location","pallet rack","bulk storage","ISPM 15","gudang B3","MSDS","CoA","mill test certificate","TPS","kartu stok","K3L"]},"headers":[],"relativePath":"sop/penyimpanan-barang.md","filePath":"sop/penyimpanan-barang.md"}'),r={name:"sop/penyimpanan-barang.md"};function l(s,a,d,u,k,p){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="sop-penyimpanan-barang" tabindex="-1">SOP Penyimpanan Barang <a class="header-anchor" href="#sop-penyimpanan-barang" aria-label="Permalink to &quot;SOP Penyimpanan Barang&quot;">​</a></h1><p class="lead">Dipakai setelah material dinyatakan sesuai di penerimaan, sampai material tersimpan di lokasinya dan tercatat. Isinya diringkas dari Instruksi Kerja Penempatan Material/Barang Gudang Teknik.</p><h2 id="tujuan" tabindex="-1">Tujuan <a class="header-anchor" href="#tujuan" aria-label="Permalink to &quot;Tujuan&quot;">​</a></h2><ul><li>Memindahkan dan menyimpan seluruh material yang dinyatakan <strong>PASSED</strong> (sesuai) oleh Good Received ke area penyimpanan secara akurat, aman, dan efisien.</li><li>Mencegah penurunan mutu (<em>deterioration</em>), kerusakan fisik, kontaminasi, dan kehilangan stok.</li><li>Menjamin kepatuhan terhadap K3L (Keselamatan, Kesehatan Kerja, dan Lingkungan).</li></ul><p>Semuanya sejalan dengan moto Gudang Teknik: <em>a place for everything and everything in its place</em>.</p><h2 id="berlaku-untuk" tabindex="-1">Berlaku untuk <a class="header-anchor" href="#berlaku-untuk" aria-label="Permalink to &quot;Berlaku untuk&quot;">​</a></h2><p>Seluruh area penyimpanan Gudang Teknik, untuk lima klasifikasi material: material part, consumable, raw material, ATK dan office supply, serta chemical (bahan kimia).</p><h2 id="peran" tabindex="-1">Peran <a class="header-anchor" href="#peran" aria-label="Permalink to &quot;Peran&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Peran</th><th>Tanggung jawab</th></tr></thead><tbody><tr><td data-label="Peran"><strong>Supervisor Gudang</strong></td><td data-label="Tanggung jawab">Mengawasi kepatuhan terhadap instruksi kerja.</td></tr><tr><td data-label="Peran"><strong>Good Received</strong></td><td data-label="Tanggung jawab">Menempatkan material yang dinyatakan PASSED/OK di lokasi yang sudah ditentukan di database. Kalau ada kondisi tertentu, material ditaruh dulu di tempat penampungan sementara (TPS).</td></tr></tbody></table><h2 id="yang-perlu-disiapkan" tabindex="-1">Yang perlu disiapkan <a class="header-anchor" href="#yang-perlu-disiapkan" aria-label="Permalink to &quot;Yang perlu disiapkan&quot;">​</a></h2><ul><li>Komputer, printer, dan sistem ERP/WMS.</li><li>Alat tulis dan kartu stok.</li><li>APD: safety helmet, kacamata pengaman, safety shoes, sarung tangan, back support, dan masker, sesuai pekerjaannya.</li><li>Alat bantu: troli, tangga portabel, forklift, palet, dan webbing sling.</li></ul><h2 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h2><ol><li><strong>Pastikan material sudah dinyatakan sesuai.</strong> Material tidak boleh dipindahkan dari area inspeksi sebelum dinyatakan sesuai di <a href="./penerimaan-barang">penerimaan</a>.</li><li><strong>Cek dokumen pendukung.</strong> Report Inspection atau CoA (<em>Certificate of Analysis</em>), Mill Test Certificate, atau MSDS (<em>Material Safety Data Sheet</em>) harus lengkap dan dilampirkan pada lembar penerimaan barang.</li><li><strong>Cek kemasan.</strong> Pastikan kemasan luar tidak bocor, tidak tumpah, dan tidak rusak saat dipindahkan dari area inspeksi.</li><li><strong>Tempatkan material sesuai klasifikasinya.</strong> Lihat tabel di bawah.</li><li><strong>Terapkan FIFO dan FEFO.</strong> Barang yang masuk lebih dulu dan barang yang lebih dulu kedaluwarsa harus keluar lebih dulu.</li><li><strong>Perbarui kartu stok</strong>: tanggal masuk, nomor purchase order (PO), jumlah barang, dan saldo akhir.</li></ol><h2 id="penempatan-berdasarkan-klasifikasi" tabindex="-1">Penempatan berdasarkan klasifikasi <a class="header-anchor" href="#penempatan-berdasarkan-klasifikasi" aria-label="Permalink to &quot;Penempatan berdasarkan klasifikasi&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Klasifikasi</th><th>Cara penyimpanan</th></tr></thead><tbody><tr><td data-label="Klasifikasi"><strong>Material part</strong> (suku cadang mekanik, elektrik, instrumen)</td><td data-label="Cara penyimpanan">Selective pallet rack untuk part besar atau berat. Bin box, shelving rack, atau dus bekas kemasan untuk part kecil. Material berbahan utama karet disimpan di ruang bersuhu dingin terkontrol. Setiap bin box wajib punya identitas <em>bin location</em> yang 100% sama dengan lokasi di ERP/WMS.</td></tr><tr><td data-label="Klasifikasi"><strong>Consumable</strong> (barang habis pakai produksi)</td><td data-label="Cara penyimpanan">Hindari penumpukan berlebih.</td></tr><tr><td data-label="Klasifikasi"><strong>Raw material</strong> (bahan baku utama produksi)</td><td data-label="Cara penyimpanan">Disimpan di area <em>bulk storage</em> (hall yang luas). Wajib dialasi palet plastik atau kayu standar ISPM 15, tidak boleh langsung di lantai. Ikuti batas tumpukan (<em>tiers stacking</em>) pada kemasan produsen. Jalur forklift harus bebas dari barang yang menjorok keluar palet atau rak (<em>overhang</em>). Material khusus disimpan di ruang bersuhu dingin terkontrol.</td></tr><tr><td data-label="Klasifikasi"><strong>ATK dan office supply</strong></td><td data-label="Cara penyimpanan">Tinta cartridge dan toner disimpan di ruang bersuhu dingin terkontrol. Bahan mudah terbakar seperti kertas dan kardus dijauhkan dari panel listrik dan sumber panas.</td></tr><tr><td data-label="Klasifikasi"><strong>Chemical</strong> (bahan kimia padat, cair, dan gas)</td><td data-label="Cara penyimpanan">Wajib di <strong>Gudang B3</strong> yang punya banyak ventilasi, exhaust fan, dan lantai penampung dengan bak kontrol tumpahan. MSDS berbahasa Indonesia atau Inggris ditempel di dekat area simpan. Kemasan wajib berlabel simbol bahan berbahaya. Sawdust (penyerap tumpahan), eyewash station, dan APAR powder/CO2 harus tersedia dan tidak terhalang.</td></tr></tbody></table><p>Semua klasifikasi memakai prinsip <strong>FIFO dan FEFO</strong>.</p><h2 id="tips-penataan" tabindex="-1">Tips penataan <a class="header-anchor" href="#tips-penataan" aria-label="Permalink to &quot;Tips penataan&quot;">​</a></h2><ul><li>Kalau lokasi penuh atau belum ditentukan, tanyakan ke pembimbing. Jangan menaruh barang di sembarang tempat.</li><li>Pastikan label menghadap ke luar dan mudah dibaca.</li><li>Letakkan barang berat di rak bawah dan barang ringan di rak atas.</li><li>Kalau barang dipindahkan ke rak lain, perbarui lokasinya di database pada hari yang sama.</li></ul><h2 id="cek-setiap-hari" tabindex="-1">Cek setiap hari <a class="header-anchor" href="#cek-setiap-hari" aria-label="Permalink to &quot;Cek setiap hari&quot;">​</a></h2><ul class="daftar-periksa"><li>Tidak ada barang di lantai jalur jalan, dan raw material selalu di atas palet.</li><li>Barang berada di lokasi yang sesuai database, dan <em>bin location</em> sama dengan ERP/WMS.</li><li>Kartu stok di rak sudah diperbarui.</li><li>Label rak dan label barang terbaca.</li><li>Barang lama atau yang lebih dulu kedaluwarsa berada di depan (FIFO/FEFO).</li><li>Kemasan consumable dan chemical tertutup rapat dan tidak bocor.</li><li>MSDS, sawdust, eyewash station, dan APAR di Gudang B3 tersedia dan tidak terhalang.</li><li>Tidak ada barang rusak yang tercampur dengan stok layak pakai.</li><li>Barang di rak reservasi diberi keterangan untuk divisi mana.</li></ul><h2 id="perhatian-keselamatan" tabindex="-1">Perhatian keselamatan <a class="header-anchor" href="#perhatian-keselamatan" aria-label="Permalink to &quot;Perhatian keselamatan&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Risiko di area penyimpanan</p><ul><li>Jangan memanjat rak. Gunakan tangga atau alat bantu yang disediakan.</li><li>Jangan menumpuk barang melebihi batas rak atau batas tumpukan pada kemasan.</li><li>Jaga agar jalur jalan, jalur forklift, pintu darurat, dan alat pemadam api tidak terhalang.</li><li>Bahan mudah terbakar disimpan jauh dari sumber panas atau percikan api.</li></ul></div><h2 id="baca-juga" tabindex="-1">Baca juga <a class="header-anchor" href="#baca-juga" aria-label="Permalink to &quot;Baca juga&quot;">​</a></h2><ul><li><a href="/WareHouse/alur-kerja/layout-gudang">Layout Gudang</a></li><li><a href="/WareHouse/divisi/manajemen-inventory#write-off">Manajemen Inventory: write off dan FIFO</a></li><li><a href="/WareHouse/sop/k3-gudang">K3 di Gudang</a></li></ul><h2 id="acuan" tabindex="-1">Acuan <a class="header-anchor" href="#acuan" aria-label="Permalink to &quot;Acuan&quot;">​</a></h2><p>ISO 45001 dan ISO 14001, edisi terakhir.</p>',26)])])}const g=n(r,[["render",l]]);export{m as __pageData,g as default};
